cd /tmp/vally-eval-trial-iqUAff && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Gold,
}

public sealed record CalculatePayableTotalQuery(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    // Stub: compiles only; the approved discount is deliberately not implemented yet.
    public decimal Handle(CalculatePayableTotalQuery query) => query.Subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void S1_Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalQuery(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~LoyaltyDiscountTests" --verbosity quiet 2>&1 | tail -25

